                    | "confidential"
                    | "private"
                    | "not provided"
                    | "not-provided"
                    | "not disclosed"
                    | "address withheld"
                    | "not applicable"
                    | "n/a"
            );
        let normalized = usable.then_some(normalized);
        Self {
            match_quality: AddressMatchQuality::from_normalized(normalized.as_deref()),
            raw: Some(raw.clone()),
            normalized,
            source_field: Some(field.clone()),
        }
    }
